//! 👶️ One child identity is originally issued in separate paid parent turns and lends only actual supplier inputs.
use super::*;

/// 🪢️ Holds the upstream original source through initial child births, callbacks and witnessed physical return.
pub struct OriginalCallerChildSource{upstream:ManuallyDrop<Option<OriginalCallerSourceLoan>>,cancel:ManuallyDrop<Option<CancelToken>>,cancel_retiring:ManuallyDrop<Option<CancelTokenRetirement>>,initial_child_ledger:ManuallyDrop<Option<JobPayloadAuthority>>,parent:ManuallyDrop<Option<OriginalCallerSourceParent>>,operation:OperationId,generation:Generation,ready:bool,closing:bool}
impl OriginalCallerChildSource{
 pub fn begin(parent:&OriginalCallerSourceParent,cx:&mut StepContext<'_>,operation:OperationId,generation:Generation)->Result<Option<Self>,OriginalTurnFailure>{if operation.0==0||generation.0==0{return Err(refused("original child source requires its declared nonzero business identity").into())}let Some(upstream)=parent.admit_loan(cx)?else{return Ok(None)};Ok(Some(Self{upstream:ManuallyDrop::new(Some(upstream)),cancel:ManuallyDrop::new(None),cancel_retiring:ManuallyDrop::new(None),initial_child_ledger:ManuallyDrop::new(None),parent:ManuallyDrop::new(None),operation,generation,ready:false,closing:false}))}
 fn validate_parent(&self,parent:&OriginalCallerSourceParent,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{let upstream=self.upstream.as_ref().ok_or_else(||refused("original child source has already returned its parent loan"))?;let witness=parent.original.as_ref().ok_or_else(||refused("original child parent source has already entered retirement"))?;let original=upstream.original.as_ref().ok_or_else(||refused("original child source has no upstream strong witness"))?;if !matches_roots(original.get(),cx)||witness.identity()!=original.identity(){return Err(refused("original child source requires its same still-retained initiating parent").into())}if !self.closing{upstream.validate_context(cx)?;}Ok(())}
 pub fn admit_step(&mut self,parent:&OriginalCallerSourceParent,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate_parent(parent,cx)?;if self.closing{return Err(refused("closing original child source cannot admit another phase").into())}if self.ready{return Ok(true)}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}if self.parent.is_some(){self.ready=true;return Ok(true)}if self.cancel.is_none(){if let Some(cancel)=cx.admit_original_cancel_alias()?{*self.cancel=Some(cancel);cx.consume_fuel(1);}return Ok(false)}if self.initial_child_ledger.is_none(){if let Some((ledger,progress))=JobPayloadAuthority::admit(self.operation,self.generation,cx.retained_grant())?{*self.initial_child_ledger=Some(ledger);cx.consume_retained(progress)?;cx.consume_fuel(1);}return Ok(false)}let grant=cx.retained_grant();let demand=OriginalCallerSourceParent::admission_demand();if !permits(grant,demand){return Ok(false)}let authority=self.initial_child_ledger.take().unwrap();let cancel=self.cancel.take().unwrap();match OriginalCallerSourceParent::admit(authority,cancel,grant){Ok((mut child,progress))=>{child.borrowed_cancel=true;*self.parent=Some(child);cx.consume_retained(progress)?;cx.consume_fuel(1);Ok(false)},Err((error,authority,cancel))=>{*self.initial_child_ledger=Some(authority);*self.cancel=Some(cancel);Err(error.into())}}}
 pub fn parent(&self)->Result<&OriginalCallerSourceParent,ValueError>{if !self.ready||self.closing{return Err(refused("original child source must finish its declared paid admission before lending"))}self.parent.as_ref().ok_or_else(||refused("original child parent is absent"))}
 pub fn with_context<T>(&self,parent:&OriginalCallerSourceParent,cx:&mut StepContext<'_>,requested:RetainedCloneGrant,run:impl for<'turn> FnOnce(&mut StepContext<'turn>)->Result<T,OriginalTurnFailure>)->Result<OriginalChildTurnReturn<T>,OriginalTurnFailure>{
  self.validate_parent(parent,cx)?;if !self.ready&&!self.closing{return Err(refused("original child callback cannot precede its paid source admission").into())}let child_parent=self.parent.as_ref().ok_or_else(||refused("original child callback has no live child source parent"))?;let before=cx.retained_progress();let original=OriginalRetainedLoanIdentity::capture(cx);let grant=narrowed_ceiling(cx,requested)?;let fuel=cx.fuel_remaining;let work=cx.work_units_spent;let clock=cx.clock.get();let source_epoch=cx.source_epoch;let payload_page_granted=cx.payload_page_granted;let retained_work=cx.retained_work;let stage=cx.stage;let budget=StepBudget{fuel,deadline_us:cx.deadline_us,retained:grant};
  let(result,matched,remaining,returned_clock,returned_page,returned_work,returned_stage,returned_cpu)={let mut child=child_parent.borrow_context(budget,cx.now_us,cx.preview_sequence,cx.retained_progress)?;if !std::ptr::eq(child.original_source_parent()?,child_parent){return Err(refused("original child context accessor changed its actual paid parent").into())}child.work_units_spent=work;child.clock.set(clock);child.source_epoch=source_epoch;child.payload_page_granted=payload_page_granted;child.retained_work=retained_work;child.stage=stage;let identity=OriginalRetainedLoanIdentity::capture(&child);let result=run(&mut child);let matched=identity.matches(&child)&&child.source_epoch==source_epoch&&child.fuel_remaining<=fuel&&matches_roots(child_parent.original.as_ref().unwrap().get(),&child);(result,matched,child.fuel_remaining,child.clock.get(),child.payload_page_granted,child.retained_work,child.stage,child.work_units_spent)};
  let after=cx.retained_progress();let receipt_refusal=if !matched||!original.matches(cx){Some(refused("original child callback replaced its live source, recipient or incoming authority"))}else{delta(before,after).err().or_else(||(!after.fits(grant)).then(||refused("original child callback exceeded its actual parent loan ceiling")))};if matched&&original.matches(cx){cx.fuel_remaining=remaining;cx.work_units_spent=returned_cpu;cx.clock.set(returned_clock);cx.payload_page_granted=returned_page;cx.retained_work=returned_work;cx.stage=returned_stage;}Ok(OriginalChildTurnReturn{original:ManuallyDrop::new(Some((result,receipt_refusal))),before,after})
 }
 pub fn terminal_is_empty(&self)->bool{self.upstream.is_none()&&self.cancel.is_none()&&self.cancel_retiring.is_none()&&self.initial_child_ledger.is_none()&&self.parent.is_none()}
 pub fn close_step(&mut self,parent:&OriginalCallerSourceParent,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}self.validate_parent(parent,cx)?;self.closing=true;self.ready=false;if cx.should_yield(){return Ok(InteractiveJobCloseStep::Pending{progress:Default::default()})}let grant=cx.retained_grant();let progress=if let Some(child)=self.parent.as_mut(){let step=child.close_witnessed(grant,Some(parent.cancellation()?)).map_err(|error|OriginalTurnFailure::debit_original(error,cx))?;if child.terminal_is_empty(){self.parent.take();}step.progress()}else if let Some(ledger)=self.initial_child_ledger.as_mut(){let step=ledger.close_step(grant).map_err(|error|OriginalTurnFailure::debit_original(error,cx))?;if ledger.terminal_is_empty(){self.initial_child_ledger.take();}step.progress()}else if self.cancel.is_some()||self.cancel_retiring.is_some(){if self.cancel_retiring.is_none(){*self.cancel_retiring=Some(CancelTokenRetirement::from_token(self.cancel.take().unwrap()));}let retiring=self.cancel_retiring.as_mut().unwrap();let step=retiring.return_alias_step(parent.cancellation()?,grant).map_err(|error|OriginalTurnFailure::debit_original(cancel_refusal(error),cx))?;if retiring.terminal_is_empty(){self.cancel_retiring.take();}step.progress()}else{let step=self.upstream.as_mut().unwrap().close_step(parent,cx)?;if self.upstream.as_ref().unwrap().terminal_is_empty(){self.upstream.take();}return Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress:step.progress()}}else{InteractiveJobCloseStep::Pending{progress:step.progress()}})};cx.consume_retained(progress)?;if progress.copied_items>0{cx.consume_fuel(1);}Ok(InteractiveJobCloseStep::Pending{progress})}
}
impl Drop for OriginalCallerChildSource{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original child source reached Drop before all original births and upstream source loan returned")}}

/// 🧾️ Keeps the entire semantic value and independent receiving cause owned after actual parent spending is already posted.
#[derive(Debug)]
pub struct OriginalChildTurnReturn<T>{original:ManuallyDrop<Option<(Result<T,OriginalTurnFailure>,Option<ValueError>)>>,before:RetainedCloneProgress,after:RetainedCloneProgress}
impl<T> OriginalChildTurnReturn<T>{pub fn raw_progress(&self)->Result<RetainedCloneProgress,ValueError>{delta(self.before,self.after)}pub fn original_receiving(&self)->(RetainedCloneProgress,RetainedCloneProgress){(self.before,self.after)}pub fn admitted(&self)->Option<&Result<T,OriginalTurnFailure>>{let(original,refusal)=self.original.as_ref()?;refusal.is_none().then_some(original)}pub fn receipt_refusal(&self)->Option<&ValueError>{self.original.as_ref().and_then(|(_,refusal)|refusal.as_ref())}pub fn into_original(mut self)->Result<Result<T,OriginalTurnFailure>,Self>{if self.receipt_refusal().is_some(){return Err(self)}Ok(self.original.take().expect("original child return extracted once").0)}pub fn terminal_is_empty(&self)->bool{self.original.is_none()}}
impl<T:RetireOwned> RetireOwned for OriginalChildTurnReturn<T>{fn retirement(mut self)->Box<dyn RetirementCursor>{self.original.take().retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.original.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl<T> Drop for OriginalChildTurnReturn<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original child semantic return reached Drop before admitted extraction or whole granted retirement")}}
fn permits(grant:RetainedCloneGrant,demand:RetirementDemand)->bool{grant.maximum_items>0&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth}
fn narrowed_ceiling(cx:&StepContext<'_>,requested:RetainedCloneGrant)->Result<RetainedCloneGrant,ValueError>{let posted=cx.retained_progress();if !posted.fits(cx.retained){return Err(refused("original child parent recipient already exceeds its incoming ceiling"))}let remaining=cx.retained_grant();let add=|paid:usize,wanted:usize,available:usize|paid.checked_add(wanted.min(available)).ok_or_else(||refused("original child loan ceiling overflow"));Ok(RetainedCloneGrant{maximum_items:add(posted.copied_items,requested.maximum_items,remaining.maximum_items)?,maximum_copy_bytes:add(posted.copied_bytes,requested.maximum_copy_bytes,remaining.maximum_copy_bytes)?,maximum_capacity_bytes:add(posted.retained_capacity_bytes,requested.maximum_capacity_bytes,remaining.maximum_capacity_bytes)?,maximum_release_bytes:add(posted.released_bytes,requested.maximum_release_bytes,remaining.maximum_release_bytes)?,maximum_depth:remaining.maximum_depth.min(requested.maximum_depth)})}
